<script lang="ts">
	import Octicon from "$lib/components/Octicon.svelte";
	import { getSourceProviderAdapter } from "$lib/source-provider";
	import LaunchConfirm from "./LaunchConfirm.svelte";
	import MappingReview from "./MappingReview.svelte";
	import type { NewMigrationController } from "./workflow.svelte";

	let { controller }: { controller: NewMigrationController } = $props();
	let repositoryReviewOpen = $state(false);
	const capabilities = $derived(getSourceProviderAdapter(controller.sourceProvider || "github").capabilities);
	function selectMode(mode: "dry-run" | "production"): void { controller.form.state.migrationMode = mode; controller.error = ""; if (mode === "dry-run") controller.productionConfirmationOpen = false; }
</script>

<section class="overflow-hidden rounded-md border border-gray-700 bg-gray-950">
	<header class="flex flex-col gap-3 border-b border-gray-700 bg-gray-900/70 px-5 py-5 sm:flex-row sm:items-center sm:justify-between lg:px-7"><div><div class="flex flex-wrap items-center gap-2"><h2 class="text-base font-semibold text-gray-50">{controller.reviewModel.title}</h2><span class="inline-flex items-center gap-1.5 rounded-full bg-green-500/15 px-2.5 py-1 text-xs font-medium text-green-400"><Octicon name="check-circle-fill" size={12} />Ready</span></div><p class="mt-1 text-sm text-gray-400">Review the resolved path, repository mappings, and launch behavior.</p></div><div class="text-xs text-gray-500">{controller.reviewModel.repositoryCount} {controller.reviewModel.repositoryCount === 1 ? "repository" : "repositories"}</div></header>
	<div class="grid border-b border-gray-700 md:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)]"><div class="px-5 py-5 lg:px-7"><span class="text-xs font-medium uppercase text-gray-500">Source</span><div class="mt-2 flex items-center gap-2 text-sm text-gray-100"><Octicon name={controller.sourceProvider === "github" ? "mark-github" : controller.sourceProvider === "gitlab" ? "gitlab-logo" : "bitbucket-logo"} size={16} /><span>{controller.sourcePlatformLabel}</span></div></div><div class="flex items-center justify-center border-y border-gray-700 px-4 py-2 text-gray-600 md:border-x md:border-y-0"><Octicon name="arrow-right" size={16} /></div><div class="px-5 py-5 lg:px-7"><span class="text-xs font-medium uppercase text-gray-500">Target</span><div class="mt-2 flex items-center gap-2 text-sm text-gray-100"><Octicon name="mark-github" size={16} /><span>{controller.selectedTargetProfile ? controller.targetDisplayName(controller.selectedTargetProfile) : "GitHub"}</span></div></div></div>
	<div class="px-5 py-5 lg:px-7"><div class="flex flex-wrap items-center justify-between gap-3"><div><h3 class="text-xs font-semibold uppercase text-gray-500">Repository mappings</h3><p class="mt-1 text-xs text-gray-600">Source names are normalized before submission.</p></div>{#if controller.mode === "batch"}<button type="button" onclick={() => (repositoryReviewOpen = true)} class="inline-flex h-9 items-center gap-2 rounded-md border border-gray-600 px-3 text-xs font-medium text-gray-300 transition-colors hover:bg-gray-800 hover:text-gray-50"><Octicon name="list-unordered" size={16} />Review all {controller.reviewModel.repositoryCount}</button>{/if}</div><div class="mt-3 divide-y divide-gray-700 overflow-hidden rounded-md border border-gray-700">{#each controller.reviewModel.repositoryMappings as mapping, index (`${mapping.source}:${index}`)}<div class="grid gap-1 bg-gray-900 px-4 py-3 text-sm sm:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] sm:items-center sm:gap-3"><span class="truncate font-mono text-gray-300">{mapping.source}</span><Octicon name="arrow-right" size={12} class="hidden text-gray-600 sm:block" /><span class="truncate font-mono text-gray-100">{mapping.target}</span></div>{/each}</div>{#if controller.reviewModel.additionalRepositoryCount > 0}<p class="mt-2 text-xs text-gray-500">+ {controller.reviewModel.additionalRepositoryCount} more</p>{/if}</div>
	<div class="grid border-t border-gray-700 lg:grid-cols-[minmax(0,1.25fr)_minmax(18rem,0.75fr)]"><div class="border-b border-gray-700 px-5 py-5 lg:border-b-0 lg:border-r lg:px-7"><span class="block text-xs font-semibold uppercase text-gray-500">Run mode</span>{#if capabilities.migrationMode}<div class="mt-3 grid grid-cols-2 gap-2"><button type="button" aria-pressed={controller.form.state.migrationMode === "dry-run"} onclick={() => selectMode("dry-run")} class="flex min-h-16 items-start gap-2.5 rounded-md border p-3 text-left {controller.form.state.migrationMode === 'dry-run' ? 'border-blue-500/50 bg-blue-500/10' : 'border-gray-700 bg-gray-900'}"><Octicon name="beaker" size={16} class="text-blue-400" /><span><span class="block text-sm font-medium text-gray-100">Dry run</span><span class="text-xs text-gray-500">Test without locking sources</span></span></button><button type="button" aria-pressed={controller.form.state.migrationMode === "production"} onclick={() => selectMode("production")} class="flex min-h-16 items-start gap-2.5 rounded-md border p-3 text-left {controller.form.state.migrationMode === 'production' ? 'border-amber-500/50 bg-amber-500/10' : 'border-gray-700 bg-gray-900'}"><Octicon name="rocket" size={16} class="text-amber-400" /><span><span class="block text-sm font-medium text-gray-100">Production</span><span class="text-xs text-gray-500">Lock and archive sources</span></span></button></div>{:else}<div class="mt-3 text-sm text-gray-400">Server-managed execution mode</div>{/if}</div><div class="px-5 py-5 lg:px-7"><span class="block text-xs font-semibold uppercase text-gray-500">Capacity</span><div class="mt-3 flex items-start gap-2"><Octicon name={controller.atCapacity ? "hourglass" : "pulse"} size={16} class={controller.atCapacity ? "text-amber-400" : "text-green-400"} /><p class="text-sm text-gray-300">{controller.reviewModel.queueMessage}</p></div></div></div>
	<footer class="flex flex-col gap-3 border-t border-gray-700 px-5 py-4 sm:flex-row sm:items-center sm:justify-between lg:px-7"><button type="button" onclick={() => controller.goBack()} class="inline-flex h-10 items-center justify-center gap-2 rounded-md border border-gray-600 px-4 text-sm font-medium text-gray-300 hover:bg-gray-800"><Octicon name="chevron-left" size={16} />Back</button><button type="submit" disabled={controller.submitting || !controller.readyForSubmission} class="inline-flex h-10 items-center justify-center gap-2 rounded-md px-5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50 {controller.form.state.migrationMode === 'production' ? 'bg-amber-600 hover:bg-amber-500' : 'bg-green-600 hover:bg-green-500'}">{#if controller.submitting}Starting...{:else}<Octicon name="rocket" size={16} />{controller.reviewModel.launchLabel}{/if}</button></footer>
</section>

<MappingReview bind:open={repositoryReviewOpen} mappings={controller.reviewModel.allRepositoryMappings} />
<LaunchConfirm bind:open={controller.productionConfirmationOpen} repositoryCount={controller.reviewModel.repositoryCount} submitting={controller.submitting} error={controller.error} onConfirm={() => controller.confirmProductionLaunch()} />